169	  const doe = z - era * 146097;
170	  const yoe = Math.floor((doe - Math.floor(doe / 1460) + Math.floor(doe / 36524) - Math.floor(doe / 146096)) / 365);
171	  const doy = doe - (365 * yoe + Math.floor(yoe / 4) - Math.floor(yoe / 100));
172	  const mp = Math.floor((5 * doy + 2) / 153);
173	  const d = doy - Math.floor((153 * mp + 2) / 5) + 1;
174	  const m = mp < 10 ? mp + 3 : mp - 9;
175	  const y = yoe + era * 400 + (m <= 2 ? 1 : 0);
176	  return `${String(y).padStart(4, '0')}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
