import { HttpClient } from '@angular/common/http';
import { Injectable, computed, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Claim, toCents } from './claims';
import { Grade } from './people';
import { Session } from './session';

export interface Rate {
  grade: Grade;
  /** yyyy-mm-dd the rate is in force from; null for a rate in force from the beginning of time. */
  from: string | null;
  /** A percent, always with two decimals, e.g. "12.50". */
  rate: string;
}

/** A rate the store accepts: a percent of 0 or more, below 1000, with at most two decimals. */
export const RATE = /^\d{1,3}(\.\d{1,2})?$/;

/**
 * Cents due on an amount in cents at a rate (a percent with two decimals): amount times rate
 * divided by 100, rounded half to even to whole cents. Exact, as the rate is taken in hundredths.
 */
export function dueCents(cents: number, rate: string): number {
  const product = BigInt(cents) * BigInt(toCents(rate));
  const whole = product / 10000n;
  const rest = product % 10000n;
  return Number(rest > 5000n || (rest === 5000n && whole % 2n === 1n) ? whole + 1n : whole);
}

/**
 * The rate among these in force on a date (yyyy-mm-dd): the one with the latest from-date on or
 * before it, a rate with no from-date applying from the beginning of time. Undefined when none applies.
 */
export function rateOn(rates: Rate[], date: string): string | undefined {
  let best: Rate | undefined;
  for (const r of rates) {
    if (r.from !== null && r.from > date) continue;
    if (best === undefined || (best.from ?? '') < (r.from ?? '')) best = r;
  }
  return best?.rate;
}

// The rates for each grade on the active sheet, per from-date, read from and written to the store.
@Injectable({ providedIn: 'root' })
export class Rates {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  readonly all = signal<Rate[]>([]);

  /** Each grade's rates, by grade. */
  readonly ofGrade = computed(() => {
    const out = new Map<Grade, Rate[]>();
    for (const r of this.all()) out.set(r.grade, [...(out.get(r.grade) ?? []), r]);
    return out;
  });

  /** Each grade's rate in force on the sheet's today; a grade with none is absent. */
  readonly byGrade = computed(() => {
    const today = this.session.today() ?? '';
    const out = new Map<Grade, string>();
    for (const [grade, rates] of this.ofGrade()) {
      const rate = rateOn(rates, today);
      if (rate !== undefined) out.set(grade, rate);
    }
    return out;
  });

  /** The grade's rate in force on a date; undefined when none applies. */
  on(grade: Grade, date: string): string | undefined {
    return rateOn(this.ofGrade().get(grade) ?? [], date);
  }

  /**
   * A claim's due in cents: a settled claim's as fixed when it was settled; any other claim's at
   * the grade's rate in force on the claim's date, raised to the sheet's floor. Undefined (n/a) when
   * there was or is no such rate.
   */
  dueOf(claim: Claim, grade: Grade): number | undefined {
    if (claim.status === 'SETTLED') return claim.settledDue === null ? undefined : toCents(claim.settledDue);
    const rate = this.on(grade, claim.date);
    if (rate === undefined) return undefined;
    const floor = this.session.floor();
    return Math.max(dueCents(toCents(claim.amount), rate), floor === null ? 0 : toCents(floor));
  }

  async reload(): Promise<void> {
    try {
      this.all.set(await firstValueFrom(this.http.get<Rate[]>(this.url(), { headers: this.headers() })));
    } catch {
      this.all.set([]);
    }
  }

  /** Set a grade's rate from a date (or from the beginning of time), replacing any it had then. */
  async set(grade: Grade, rate: string, from: string | null): Promise<void> {
    const saved = await firstValueFrom(
      this.http.put<Rate>(`${this.url()}/${grade}`, { rate: rate.trim(), from }, { headers: this.headers() }),
    );
    this.all.update((list) => [
      ...list.filter((r) => r.grade !== saved.grade || r.from !== saved.from),
      saved,
    ]);
  }

  private url(): string {
    const id = this.session.sheetId();
    if (!id) throw new Error('no sheet loaded');
    return `/api/sheets/${encodeURIComponent(id)}/rates`;
  }

  private headers(): Record<string, string> {
    const user = this.session.user();
    if (!user) throw new Error('not signed in');
    return { 'X-User': user };
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from './session';

export interface Claim {
  id: number;
  personId: number;
  /** Always with two decimals, e.g. "2.50". */
  amount: string;
  /** yyyy-mm-dd */
  date: string;
  note: string;
  status: ClaimStatus;
  /** The sheet's number given when the claim was opened; null for a draft; a voided claim keeps it. */
  number: number | null;
  /** The due fixed when the claim was settled, two decimals; null if not settled or it had no rate then. */
  settledDue: string | null;
  /** The user who opened the claim; null while it has not been opened. That user cannot settle it. */
  openedBy: string | null;
}

/** DRAFT, then OPEN, then SETTLED; a DRAFT or OPEN claim can be VOID instead. */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'SETTLED' | 'VOID';

/** The status changes a claim can be asked for, as named in the store's API. */
export type ClaimAction = 'open' | 'settle' | 'void';

/**
 * Whether the claim counts toward claimed, due-total and every total: an OPEN or SETTLED one, but
 * not an OPEN one while its person is on hold.
 */
export function counts(claim: Claim, person: { held: boolean }): boolean {
  return claim.status === 'SETTLED' || (claim.status === 'OPEN' && !person.held);
}

/** Days since 1970-01-01 of a yyyy-mm-dd date (proleptic Gregorian), without reading any clock. */
function epochDay(date: string): number {
  const [y0, m, d] = date.split('-').map(Number);
  const y = m <= 2 ? y0 - 1 : y0;
  const era = Math.floor(y / 400);
  const yoe = y - era * 400;
  const doy = Math.floor((153 * (m + (m > 2 ? -3 : 9)) + 2) / 5) + d - 1;
  const doe = yoe * 365 + Math.floor(yoe / 4) - Math.floor(yoe / 100) + doy;
  return era * 146097 + doe - 719468;
}

/** The yyyy-mm-dd date of a count of days since 1970-01-01. */
function fromEpochDay(days: number): string {
  const z = days + 719468;
  const era = Math.floor(z / 146097);
  const doe = z - era * 146097;
  const yoe = Math.floor((doe - Math.floor(doe / 1460) + Math.floor(doe / 36524) - Math.floor(doe / 146096)) / 365);
  const doy = doe - (365 * yoe + Math.floor(yoe / 4) - Math.floor(yoe / 100));
  const mp = Math.floor((5 * doy + 2) / 153);
  const d = doy - Math.floor((153 * mp + 2) / 5) + 1;
  const m = mp < 10 ? mp + 3 : mp - 9;
  const y = yoe + era * 400 + (m <= 2 ? 1 : 0);
  return `${String(y).padStart(4, '0')}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
}

/** A claim's due-by (yyyy-mm-dd): its date plus the sheet's terms in days. */
export function dueBy(claim: Claim, terms: number): string {
  return fromEpochDay(epochDay(claim.date) + terms);
}

/** Whether the claim is overdue: OPEN, with its due-by before the sheet's today. */
export function overdue(claim: Claim, terms: number, today: string): boolean {
  return claim.status === 'OPEN' && dueBy(claim, terms) < today;
}

export interface ClaimFields {
  amount: string;
  date: string;
  note: string;
}

/** An amount the store accepts: 0 or more, with at most two decimals. */
export const AMOUNT = /^\d{1,10}(\.\d{1,2})?$/;

/** Whole cents of a valid amount, so sums are exact. */
export function toCents(amount: string): number {
  const [whole, frac = ''] = amount.split('.');
  return Number(whole) * 100 + Number(frac.padEnd(2, '0'));
}

export function formatCents(cents: number): string {
  return `${Math.floor(cents / 100)}.${String(cents % 100).padStart(2, '0')}`;
}

// The claims kept on the active sheet, newest first, read from and written to the store.
@Injectable({ providedIn: 'root' })
export class Claims {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  readonly all = signal<Claim[]>([]);

  /** Re-read the store; until it answers no claims are shown, so none is shown out of date. */
  async reload(): Promise<void> {
    this.all.set([]);
    try {
      this.all.set(await firstValueFrom(this.http.get<Claim[]>(`${this.sheetUrl()}/claims`, { headers: this.headers() })));
    } catch {
      this.all.set([]);
    }
  }

  async add(personId: number, fields: ClaimFields): Promise<void> {
    const added = await firstValueFrom(
      this.http.post<Claim>(`${this.sheetUrl()}/people/${personId}/claims`, this.body(fields), { headers: this.headers() }),
    );
    this.all.update((list) => [added, ...list]);
  }

  /**
   * The quick-add bar: a DRAFT claim of the amount, dated the sheet's today, for the person of the
   * name; the store adds the person first (grade A) when the name is not on the sheet.
   */
  async quickAdd(name: string, amount: string): Promise<Claim> {
    const added = await firstValueFrom(
      this.http.post<Claim>(`${this.sheetUrl()}/quick-add`, { name, amount: amount.trim() }, { headers: this.headers() }),
    );
    this.all.update((list) => [added, ...list]);
    return added;
  }

  async update(id: number, fields: ClaimFields): Promise<void> {
    const saved = await firstValueFrom(
      this.http.put<Claim>(`${this.sheetUrl()}/claims/${id}`, this.body(fields), { headers: this.headers() }),
    );
    this.all.update((list) => list.map((c) => (c.id === saved.id ? saved : c)));
  }

  /** Move a claim to its next status; the store refuses a change its status does not allow. */
  async act(id: number, action: ClaimAction): Promise<void> {
    const saved = await firstValueFrom(
      this.http.post<Claim>(`${this.sheetUrl()}/claims/${id}/${action}`, null, { headers: this.headers() }),
    );
    this.all.update((list) => list.map((c) => (c.id === saved.id ? saved : c)));
  }

  private body(fields: ClaimFields) {
    return { amount: fields.amount.trim(), date: fields.date || null, note: fields.note };
  }

  private sheetUrl(): string {
    const id = this.session.sheetId();
    if (!id) throw new Error('no sheet loaded');
    return `/api/sheets/${encodeURIComponent(id)}`;
  }

  private headers(): Record<string, string> {
    const user = this.session.user();
    if (!user) throw new Error('not signed in');
    return { 'X-User': user };
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';

interface SheetView {
  id: string;
  /** The sheet's "today" (yyyy-mm-dd): every date decision and default date uses it. */
  today: string;
  /** The most due a clerk can settle a claim for, two decimals; null for no limit. */
  clerkLimit: string | null;
  /** The least any live due can be, two decimals. */
  floor: string;
  /** The terms: a claim is due by its date plus this many days. */
  terms: number;
}

// The signed-in user (a typed name, no password) and the active sheet. Everything else in the app
// is kept per sheet.
@Injectable({ providedIn: 'root' })
export class Session {
  private readonly http = inject(HttpClient);

  readonly user = signal<string | null>(null);
  readonly sheetId = signal<string | null>(null);
  /** The active sheet's "today" — use this, never the real clock, for dates in the sheet. */
  readonly today = signal<string | null>(null);
  /** The active sheet's clerk limit (two decimals); null for no limit. */
  readonly clerkLimit = signal<string | null>(null);
  /** The active sheet's floor (two decimals): every live due is at least it. */
  readonly floor = signal<string | null>(null);
  /** The active sheet's terms in days: a claim is due by its date plus these. */
  readonly terms = signal<number | null>(null);
  /** Counts sheet loads, so per-sheet data re-reads the store on every (re-)load. */
  readonly loads = signal(0);
  /** True while a sheet is being (re-)loaded, so nothing read from the store before is shown. */
  readonly loading = signal(false);

  signIn(name: string): void {
    this.user.set(name.trim());
  }

  /** Load (or re-load) a sheet by id; a never-used id starts an empty sheet. */
  async loadSheet(id: string): Promise<void> {
    const user = this.user();
    if (!user) throw new Error('not signed in');
    this.loading.set(true);
    try {
      const sheet = await firstValueFrom(
        this.http.post<SheetView>(`/api/sheets/${encodeURIComponent(id.trim())}/load`, null, {
          headers: { 'X-User': user },
        }),
      );
      this.show(sheet);
      this.loads.update((n) => n + 1);
    } finally {
      this.loading.set(false);
    }
  }

  /** Change the active sheet's "today". */
  async setToday(today: string): Promise<void> {
    const user = this.user();
    const id = this.sheetId();
    if (!user || !id) throw new Error('no sheet loaded');
    const sheet = await firstValueFrom(
      this.http.put<SheetView>(`/api/sheets/${encodeURIComponent(id)}/today`, { today }, {
        headers: { 'X-User': user },
      }),
    );
    this.show(sheet);
  }

  /** Change the active sheet's clerk limit (null for no limit), floor and terms (days). */
  async setSettings(clerkLimit: string | null, floor: string, terms: string): Promise<void> {
    const user = this.user();
    const id = this.sheetId();
    if (!user || !id) throw new Error('no sheet loaded');
    const sheet = await firstValueFrom(
      this.http.put<SheetView>(`/api/sheets/${encodeURIComponent(id)}/settings`, { clerkLimit, floor, terms }, {
        headers: { 'X-User': user },
      }),
    );
    this.show(sheet);
  }

  private show(sheet: SheetView): void {
    this.sheetId.set(sheet.id);
    this.today.set(sheet.today);
    this.clerkLimit.set(sheet.clerkLimit);
    this.floor.set(sheet.floor);
    this.terms.set(sheet.terms);
  }
}
